export default function register(api) {
  api.log('loaded');
  api.on('enemyDeath', (ev) => {
    const extras = 2;
    for (let i = 0; i < extras; i++) {
      const angle = Math.PI * 2 * api.rng.next();
      const dist = 10 + api.rng.range(4, 16);
      api.world.spawnPickup(
        ev.x + Math.cos(angle) * dist,
        ev.y + Math.sin(angle) * dist,
        'xp_small'
      );
    }
  });
}
